#include <vector>
#include <algorithm>

class Solution {
public:
    int maxXorSubarray(std::vector<int>& nums, int limit) {
        std::vector<int> allPref = {0};
        int pref = 0;
        for (int x : nums) {
            pref ^= x;
            allPref.push_back(pref);
        }
        int best = -1;
        int m = allPref.size();
        for (int i = 0; i < m; ++i) {
            for (int j = i + 1; j < m; ++j) {
                int val = allPref[i] ^ allPref[j];
                if (val <= limit) best = std::max(best, val);
            }
        }
        return best;
    }
};

import java.util.*;

class Solution {
    public int maxXorSubarray(int[] nums, int limit) {
        int[] allPref = new int[nums.length + 1];
        int pref = 0;
        allPref[0] = 0;
        for (int i = 0; i < nums.length; i++) {
            pref ^= nums[i];
            allPref[i + 1] = pref;
        }
        int best = -1;
        for (int i = 0; i < allPref.length; i++) {
            for (int j = i + 1; j < allPref.length; j++) {
                int val = allPref[i] ^ allPref[j];
                if (val <= limit) best = Math.max(best, val);
            }
        }
        return best;
    }
}

