        let pref = 0;
        for (const x of nums) {
            pref ^= x;
            allPref.push(pref);
        }
        let best = -1;
        for (let i = 0; i < allPref.length; i++) {
            for (let j = i + 1; j < allPref.length; j++) {
                const val = allPref[i] ^ allPref[j];
                if (val <= limit) best = Math.max(best, val);
            }
        }
